insert into app.business_rule_catalog(rule_key,domain,title,description,source,precedence,enforcement,status,test_status,source_ref,metadata)
values
('BENEFIT-SPONSOR-001','billing','Curtibrother sponsor-funded receivable model','Curtibrother is sponsor-funded rather than a scholarship, but migrated data cannot determine the exact split between sponsor and family receivable or how sponsor-paid amounts should count in collection KPIs. Existing player fees remain unchanged until this is explicitly decided.','approved_v2',100,'pending','pending','pending','player_benefits sponsor_funded + billing_profiles + legacy payments','{"requires_business_decision":true,"observedFees":[0,400,500],"doNotRecalculate":true}'::jsonb),
('BILL-WAIVER-001','billing','Authority for new debt waivers and charge decreases','Historical waiver adjustments preserve amount and reason but migration_opening_balance rows do not preserve the actor or role that authorized them. V2 must not expose a new waive-debt command until approval authority and guardrails are defined.','legacy',90,'pending','pending','pending','app.charge_adjustments historical waivers','{"requires_business_decision":true,"historicalRows":5,"actorEvidence":"missing","readOnlyReasonsPreserved":true}'::jsonb)
